	@ParameterizedTest
	@CsvSource({ "4,false", "4,true", "16,false", "16,true" })
	void physicalWorkIncludesPositioningAndRejectedFixedSuffixSeeks(int subjects, boolean fixedSuffix,
			@TempDir File directory) throws Exception {
		try (Fixture fixture = new Fixture(directory, "psoc")) {
			IRI predicate = VF.createIRI("urn:access:fixed-p");
			IRI firstObject = VF.createIRI("urn:access:first");
			IRI secondObject = VF.createIRI("urn:access:second");
			try (var connection = fixture.repository.getConnection()) {
				connection.begin();
				for (int subject = 0; subject < subjects; subject++) {
					IRI value = VF.createIRI("urn:access:seek-s:" + subject);
					for (IRI graph : Set.of(G1, G2, G3)) {
						connection.add(value, predicate, firstObject, graph);
						connection.add(value, predicate, secondObject, graph);
					}
				}
				connection.commit();
			}
			fixture.store.getBackingStore().getSketchBasedJoinEstimator().rebuild();
			try (SailDataset dataset = fixture.dataset()) {
				var source = new SailDatasetTripleTermSource(fixture.store.getValueFactory(), dataset);
				var owner = SailDatasetReadComposition.resolve(source, LmdbPhysicalReadComposition.class,
						LmdbPhysicalReadComposition::union).orElseThrow().planeOccurrences().getFirst().owner();
				var dictionary = owner.pinnedValueSnapshot().orElseThrow();
				long firstId = dictionary.valueStore().getStatementId(dictionary, firstObject);
				long secondId = dictionary.valueStore().getStatementId(dictionary, secondObject);
				IRI wrong = firstId < secondId ? firstObject : secondObject;
				IRI target = firstId < secondId ? secondObject : firstObject;
				assertTrue(
						dictionary.valueStore().getStatementId(dictionary, wrong) < dictionary.valueStore()
								.getStatementId(dictionary, target),
						"the first suffix representative must be rejected before seeking to the fixed target");
				StatementPattern pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
						new Var("s"), new Var("p", predicate), fixedSuffix ? new Var("o", target) : new Var("o"),
						new Var("g"));
				new LmdbDistinctRequirement(Set.of("s"), Set.of("s"), Set.of(), "fixed-suffix-physical-work")
						.annotate(pattern);
				var selected = fixture.pipeline(dataset)
						.selectGraphDistinctAccess(pattern, null, predicate, fixedSuffix ? target : null,
								LmdbGraphDistinctAccess.NamedDomain.allNamed());
				assertTrue(selected.isPresent());
				var access = selected.orElseThrow();
				try (var rows = dataset.getStatements(access.bindTo(pattern), null, predicate,
						fixedSuffix ? target : null)) {
					int count = 0;
					while (rows.hasNext()) {
						var row = rows.next();
						if (fixedSuffix) {
							assertEquals(target, row.getObject());
						}
						count++;
					}
					assertEquals(subjects, count);
					IndexReportingIterator reporter = (IndexReportingIterator) rows;
					long seeks = reporter.getDistinctCursorSkipSeekCountActual();
					System.out.println("GRAPH_FIXED_SUFFIX_SEEKS actual=" + seeks + " modeled="
							+ access.costs().planes().getFirst().candidate().randomSeeks());
					assertEquals((fixedSuffix ? 2L : 1L) * subjects, seeks,
							"fixed suffix rejection adds one actual seek per distinct subject prefix");
					assertTrue(access.costs().planes().getFirst().candidate().randomSeeks() >= seeks + 1L,
							"the bound predicate also positions the cursor once before the reported DISTINCT seeks");
				}
			}
		}
	}

