	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 2, 3, 4 })
	void carrierCloneAndSerializationEraseAuthorityAndSelectionButPreserveSemanticFilters(int filterLocation,
			@TempDir File directory)
			throws Exception {
		try (Fixture fixture = new Fixture(directory, "spoc,posc")) {
			fixture.seed(false);
			try (SailDataset dataset = fixture.dataset()) {
				StatementPattern physical = physicalPattern();
				physical.setIndependentInputScope(true);
				physical.setVariableScopeChange(true);
				physical.setContextBindingOriginInherited(true);
				if (filterLocation != 0) {
					physical.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:LITERAL");
					new Var[] { physical.getSubjectVar(), physical.getPredicateVar(), physical.getObjectVar(),
							physical.getContextVar() }[filterLocation - 1]
									.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:IRI");
				} else {
					physical.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:IRI");
				}
				var selected = fixture.pipeline(dataset)
						.selectGraphDistinctAccess(physical, null, null, null,
								LmdbGraphDistinctAccess.NamedDomain.selected(Set.of(G2)));
				assertTrue(selected.isPresent());
				StatementPattern carrier = selected.orElseThrow().bindTo(physical);
				assertNotEquals(StatementPattern.class, carrier.getClass());
				StatementPattern cloned = carrier.clone();
				ByteArrayOutputStream bytes = new ByteArrayOutputStream();
				try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
					output.writeObject(carrier);
				}
				StatementPattern serialized;
				try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
					serialized = (StatementPattern) input.readObject();
				}
				ByteArrayOutputStream clonedBytes = new ByteArrayOutputStream();
				try (ObjectOutputStream output = new ObjectOutputStream(clonedBytes)) {
					output.writeObject(cloned);
				}
				StatementPattern serializedClone;
				try (ObjectInputStream input = new ObjectInputStream(
						new ByteArrayInputStream(clonedBytes.toByteArray()))) {
					serializedClone = (StatementPattern) input.readObject();
				}
				for (StatementPattern ordinary : new StatementPattern[] { cloned, serialized, cloned.clone(),
						serializedClone }) {
					assertEquals(StatementPattern.class, ordinary.getClass());
					assertEquals(StatementPattern.Scope.NAMED_CONTEXTS, ordinary.getScope());
					assertTrue(ordinary.isIndependentInputScope());
					assertTrue(ordinary.isVariableScopeChange());
					assertTrue(ordinary.isContextBindingOriginInherited());
					assertEquals("object:IRI", ordinary.getStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER),
							"effective Var overrides must survive repeated ordinary cloning and serialization");
					assertFalse(LmdbDistinctCursorSkipSupport.ACCESS_MODE.equals(
							ordinary.getStringMetricPlanned(TelemetryMetricNames.PLANNED_INDEX_ACCESS_MODE)));
				}
			}
		}
	}

