	@Test
	void duplicateExplicitOccurrencesRetainTheirPhysicalWorkAndExcludeLargeInferredPlane(@TempDir File directory)
			throws Exception {
		try (Fixture fixture = new Fixture(directory, "spoc,posc")) {
			fixture.seed(false);
			fixture.addInferred();
			try (var admission = fixture.store.getBackingStore()
					.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null);
					SailDataset one = fixture.dataset("E");
					SailDataset two = fixture.dataset("EE")) {
				var single = fixture.pipeline(one)
						.selectGraphDistinctAccess(physicalPattern(), null, null, null,
								LmdbGraphDistinctAccess.NamedDomain.allNamed());
				var duplicate = fixture.pipeline(two)
						.selectGraphDistinctAccess(physicalPattern(), null, null, null,
								LmdbGraphDistinctAccess.NamedDomain.allNamed());
				assertTrue(single.isPresent());
				assertTrue(duplicate.isPresent());
				assertEquals(1, single.orElseThrow().costs().planes().size());
				assertEquals(2, duplicate.orElseThrow().costs().planes().size());
				assertTrue(duplicate.orElseThrow()
						.costs()
						.planes()
						.stream()
						.allMatch(LmdbGraphDistinctAccess.PlaneWork::explicit));
				assertEquals(2 * single.orElseThrow().costs().candidateScore(),
						duplicate.orElseThrow().costs().candidateScore(), 0.000001d);
			}
		}
	}

