		assertNotEquals(LmdbGraphDistinctAccess.NamedDomain.allNamed(),
				LmdbGraphDistinctAccess.NamedDomain.selected(Set.of()));
		assertTrue(LmdbGraphDistinctAccess.candidateIsCheaper(1.0d, 2.0d));
		assertFalse(LmdbGraphDistinctAccess.candidateIsCheaper(2.0d, 2.0d));
		assertFalse(LmdbGraphDistinctAccess.candidateIsCheaper(2.0d, 1.0d));
